// Reads the spike's local values. Nothing here prints a value.
//  - .env        : filled in by Mark (Neon, Netlify, LINE, Google)
//  - .env.spike  : generated by scripts/make-key.mjs (signing key, throwaway passwords)
//  - staging     : read IN PLACE from the main checkout's apps/platform/.env.local; never copied.
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const spikeRoot = resolve(here, "..");

function parse(file) {
  if (!existsSync(file)) return {};
  const out = {};
  for (const line of readFileSync(file, "utf8").split(/\r?\n/)) {
    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line);
    if (!m) continue;
    let v = m[2].trim();
    if (/^(".*"|'.*')$/.test(v) && !v.startsWith("{")) v = v.slice(1, -1);
    out[m[1]] = v;
  }
  return out;
}

// The main checkout is the worktree's "common dir" parent: <main>/.claude/worktrees/neon-spike/spike/neon
const mainCheckout = resolve(spikeRoot, "..", "..", "..", "..", "..");
const stagingFile = resolve(mainCheckout, "apps", "platform", ".env.local");

export const env = { ...parse(resolve(spikeRoot, ".env")), ...parse(resolve(spikeRoot, ".env.spike")) };

const STAGING_KEYS = ["STAGING_SUPABASE_URL", "STAGING_SUPABASE_SECRET_KEY", "STAGING_ANON_KEY", "STAGING_DB_URL"];
export function staging() {
  const all = parse(stagingFile);
  const out = {};
  for (const k of STAGING_KEYS) {
    if (!all[k]) throw new Error(`${k} is empty in the main checkout's apps/platform/.env.local`);
    out[k] = all[k];
  }
  // Safety: the spike may only ever talk to staging, never live.
  if (!out.STAGING_SUPABASE_URL.includes("qafhmdxsodeqkeznafaq")) throw new Error("STAGING_SUPABASE_URL is not the staging project");
  if (out.STAGING_DB_URL.includes("mfaqydyoweerlqsgwnay")) throw new Error("STAGING_DB_URL names the live project");
  if (!out.STAGING_DB_URL.includes("qafhmdxsodeqkeznafaq")) throw new Error("STAGING_DB_URL does not name the staging project");
  return out;
}

export function need(name) {
  if (!env[name]) throw new Error(`${name} is empty`);
  return env[name];
}

/** Scrubs anything that looks like a secret from an error message before it is shown. */
export function safe(message) {
  return String(message)
    .replace(/postgres(ql)?:\/\/[^\s"']+/g, "postgresql://<hidden>")
    .replace(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, "<jwt>")
    .replace(/npg_[A-Za-z0-9]+/g, "<hidden>");
}
